 });

+// Supuestos en docs/cambios/descuento-global.md
+test("descuento global: porcentaje sobre el total, IVA incluido sobre el total descontado", () => {
+  const items = [{ cantidad: 2, precioUnitarioCentavos: 1000 }];
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 10 }), { totalCentavos: 1800, ivaCentavos: 234, netoCentavos: 1566 });
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 0 }), calcularFactura(items));
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 100 }), { totalCentavos: 0, ivaCentavos: 0, netoCentavos: 0 });
+});
+
+test("descuento global: se redondea al centavo y se rechaza fuera de 0–100", () => {
+  const items = [{ cantidad: 1, precioUnitarioCentavos: 1001 }];
+  assert.equal(calcularFactura(items, { descuentoGlobal: 10 }).totalCentavos, 901); // 100,1 -> 100
+  assert.throws(() => calcularFactura(items, { descuentoGlobal: -1 }), RangeError);
+  assert.throws(() => calcularFactura(items, { descuentoGlobal: 101 }), RangeError);
+  assert.throws(() => calcularFactura(items, { descuentoGlobal: "10" }), RangeError);
+  assert.throws(() => calcularFactura(items, { descuentoGlobal: NaN }), RangeError);
+});
+
